  static Uint8List? _bytesFor(String key) {
    final cached = _decodedCache[key];
    if (cached != null) return cached;
    final raw = _base64ByKey[key];
    if (raw == null || raw.isEmpty) return null;
    final bytes = base64Decode(raw);
    _decodedCache[key] = bytes;
    return bytes;
  }

  @override
  Widget build(BuildContext context) {
    final bytes = _bytesFor(stickerKey);
    if (bytes != null) {
      return Image.memory(
        bytes,
        width: width,
        height: height,
        fit: fit,
        gaplessPlayback: true,
        errorBuilder: (context, error, stackTrace) {
          if (fallbackAssetPath != null && fallbackAssetPath!.isNotEmpty) {
            return R2StickerImage(
              fallbackAssetPath!,
              width: width,
              height: height,
              fit: fit,
              errorWidget: errorWidget,
            );
          }
          return errorWidget ?? const SizedBox.shrink();
        },
      );
    }
    if (fallbackAssetPath != null && fallbackAssetPath!.isNotEmpty) {
      return R2StickerImage(
        fallbackAssetPath!,
        width: width,
        height: height,
        fit: fit,
        errorWidget: errorWidget,
      );
    }
    return errorWidget ?? const SizedBox.shrink();
  }
